ARCHIVE_PUBLICATION_WRITER_SOURCE="def write_record(parent, name, raw):\n    if len(raw) > 4096:\n        for number, offset in enumerate(range(0, len(raw), 4096)):\n            write_record(parent, name + '.part-' + str(number), raw[offset:offset + 4096])\n        write_record(parent, name + '.manifest.json', json.dumps({'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest(), 'partBytes': 4096, 'partCount': (len(raw) + 4095) // 4096}, sort_keys=True).encode())\n        return\n    fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 384, dir_fd=parent)\n    try:\n        view = memoryview(raw)\n        while view:\n            count = os.write(fd, view)\n            if count <= 0:\n                raise ValueError('record_write_unknown')\n            view = view[count:]\n        os.fsync(fd)\n    finally:\n        os.close(fd)"

FIXED_ARCHIVE_CLOSURE_SOURCE="def archive_generation_closure():\n    if type(archive_fd) is not int or archive_fd < 0 or type(archive_open_fd) is not int or (archive_fd != archive_open_fd) or (type(archive_pin) is not list) or (len(archive_pin) != 9) or any((type(value) is not int for value in archive_pin)) or (archive_pin != SOURCE_ARCHIVE_PIN) or (archive_name != 'temurin.tar.gz') or (not archive_chain):\n        raise ValueError('artifact_archive_changed')\n    try:\n        guard_parents(archive_chain)\n        current = os.fstat(archive_fd)\n        named = os.stat(archive_name, dir_fd=archive_chain[-1]['fd'], follow_symlinks=False)\n        if fp(current) != archive_pin or fp(named) != archive_pin or (not stat.S_ISREG(current.st_mode)) or (not stat.S_ISREG(named.st_mode)) or (stat.S_IMODE(current.st_mode) != 384) or (current.st_uid != 1000) or (current.st_gid != 1000) or (current.st_nlink != 1):\n            raise ValueError('artifact_archive_changed')\n        if fp(os.fstat(archive_fd)) != archive_pin or fp(os.stat(archive_name, dir_fd=archive_chain[-1]['fd'], follow_symlinks=False)) != archive_pin:\n            raise ValueError('artifact_archive_changed')\n    except OSError:\n        raise ValueError('artifact_archive_changed') from None"
