PRODUCER_JOURNAL_OLD_SOURCE="def fp(i):\n    return [i.st_dev, i.st_ino, i.st_size, i.st_mtime_ns, i.st_ctime_ns, i.st_mode, i.st_uid, i.st_gid, i.st_nlink]\ndef parent_fds(path):\n    path = pathlib.Path(path)\n    if not path.is_absolute() or any((part in ('..', '.') for part in path.parts[1:])):\n        raise ValueError('census_ancestry_invalid')\n    chain = []\n    try:\n        fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)\n        chain.append({'fd': fd, 'name': '/', 'pin': fp(os.fstat(fd))})\n        for name in path.parts[1:-1]:\n            fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=chain[-1]['fd'])\n            chain.append({'fd': fd, 'name': name, 'pin': fp(os.fstat(fd))})\n        guard_parents(chain)\n        return (chain, path.name)\n    except BaseException:\n        close_parents(chain)\n        raise\ndef close_parents(chain):\n    for item in reversed(chain):\n        os.close(item['fd'])\ndef guard_parents(chain):\n    for number, item in enumerate(chain):\n        try:\n            named = os.stat('/', follow_symlinks=False) if number == 0 else os.stat(item['name'], dir_fd=chain[number - 1]['fd'], follow_symlinks=False)\n            if fp(os.fstat(item['fd'])) != item['pin'] or fp(named) != item['pin']:\n                raise ValueError('census_ancestry_changed')\n        except FileNotFoundError:\n            raise ValueError('census_ancestry_changed') from None\ndef file_digest(fd, deadline):\n    before = fp(os.fstat(fd))\n    digest = hashlib.sha256()\n    count = 0\n    os.lseek(fd, 0, 0)\n    while True:\n        if time.monotonic() > deadline:\n            raise ValueError('artifact_deadline')\n        raw = os.read(fd, 524288)\n        if not raw:\n            break\n        count += len(raw)\n        digest.update(raw)\n    if fp(os.fstat(fd)) != before:\n        raise ValueError('artifact_file_changed')\n    return (count, digest.hexdigest(), before)\ndef elf_build_ids(fd, size):\n    header = os.pread(fd, 64, 0)\n    if len(header) < 64 or header[:4] != b'\\x7fELF' or header[4] != 2 or (header[5] not in (1, 2)):\n        raise ValueError('debugger_dso_elf_changed')\n    endian = '<' if header[5] == 1 else '>'\n    offset = struct.unpack_from(endian + 'Q', header, 32)[0]\n    width, count = struct.unpack_from(endian + 'HH', header, 54)\n    if width != 56 or count > 1024 or offset + width * count > size:\n        raise ValueError('debugger_dso_elf_changed')\n    result = []\n    for number in range(count):\n        entry = os.pread(fd, width, offset + number * width)\n        if struct.unpack_from(endian + 'I', entry)[0] != 4:\n            continue\n        start = struct.unpack_from(endian + 'Q', entry, 8)[0]\n        length = struct.unpack_from(endian + 'Q', entry, 32)[0]\n        if length > 1048576 or start + length > size:\n            raise ValueError('debugger_dso_elf_changed')\n        notes = os.pread(fd, length, start)\n        at = 0\n        while at + 12 <= len(notes):\n            names, descs, kind = struct.unpack_from(endian + 'III', notes, at)\n            at += 12\n            if names > 4096 or descs > 4096 or at + (names + 3 & ~3) + (descs + 3 & ~3) > len(notes):\n                raise ValueError('debugger_dso_elf_changed')\n            name = notes[at:at + names]\n            at += names + 3 & ~3\n            desc = notes[at:at + descs]\n            at += descs + 3 & ~3\n            if kind == 3 and name == b'GNU\\x00':\n                result.append(desc.hex())\n    return result\ndef write_record(parent, name, raw):\n    if len(raw) > 4096:\n        for number, offset in enumerate(range(0, len(raw), 4096)):\n            write_record(parent, name + '.part-' + str(number), raw[offset:offset + 4096])\n        write_record(parent, name + '.manifest.json', json.dumps({'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest(), 'partBytes': 4096, 'partCount': (len(raw) + 4095) // 4096}, sort_keys=True).encode())\n        return\n    fd = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 384, dir_fd=parent)\n    try:\n        view = memoryview(raw)\n        while view:\n            count = os.write(fd, view)\n            if count <= 0:\n                raise ValueError('record_write_unknown')\n            view = view[count:]\n        os.fsync(fd)\n    finally:\n        os.close(fd)\ndef retain_raw(parent, label, raw):\n    chunks = []\n    for number, offset in enumerate(range(0, len(raw), 4096)):\n        block = bytes(raw[offset:offset + 4096])\n        name = label + '-' + str(number) + '.private'\n        write_record(parent, name, block)\n        chunks.append({'name': name, 'bytes': len(block), 'sha256': hashlib.sha256(block).hexdigest()})\n    manifest = {'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest(), 'chunks': chunks}\n    write_record(parent, label + '-manifest.json', json.dumps(manifest, sort_keys=True).encode())\n    return manifest\ndef validate_role(command, kwargs):\n    global build_root\n    if type(command) is not list or any((type(x) is not str or not x or '\\x00' in x for x in command)) or type(role_index) is not int or (role_index < 0) or (role_index >= 5):\n        raise ValueError('producer_command_refused')\n    if kwargs != {'check': False, 'capture_output': True, 'text': True, 'timeout': 60}:\n        raise ValueError('producer_command_refused')\n    jdk = str(SOURCE_TREE_DIR / 'jdk-tree' / JDK_ROOT_NAME)\n    if role_index == 0:\n        expected = [jdk + '/bin/java', '-version']\n    elif role_index == 1:\n        if len(command) != 4:\n            raise ValueError('producer_command_refused')\n        root = pathlib.Path(command[3]).parent\n        if root.parent != build_tmp or not re.fullmatch('vpn-control-jpackage-launcher-[a-z0-9_]{8}', root.name):\n            raise ValueError('producer_command_refused')\n        info = root.lstat()\n        if not stat.S_ISDIR(info.st_mode) or stat.S_IMODE(info.st_mode) != 448 or info.st_uid != 1000 or (info.st_gid != 1000):\n            raise ValueError('producer_command_refused')\n        build_root = root\n        expected = [jdk + '/bin/javac', '-d', str(root / 'classes'), str(root / 'HelloMain.java')]\n        source = HELLO_SOURCE.encode()\n        path = root / 'HelloMain.java'\n        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)\n        try:\n            info = os.fstat(fd)\n            raw = os.read(fd, 4096)\n            if raw != source or fp(info) != fp(path.lstat()) or (not stat.S_ISREG(info.st_mode)) or (info.st_nlink != 1) or (info.st_uid != 1000) or (info.st_gid != 1000):\n                raise ValueError('producer_command_refused')\n        finally:\n            os.close(fd)\n    elif build_root is None:\n        raise ValueError('producer_command_refused')\n    elif role_index == 2:\n        expected = [jdk + '/bin/jar', '--create', '--file', str(build_root / 'input/hello.jar'), '--main-class', 'HelloMain', '-C', str(build_root / 'classes'), '.']\n    elif role_index == 3:\n        expected = [jdk + '/bin/jpackage', '--type', 'app-image', '--dest', str(build_root / 'image'), '--name', 'launcher-preflight', '--input', str(build_root / 'input'), '--main-jar', 'hello.jar', '--main-class', 'HelloMain', '--add-modules', 'java.base']\n    else:\n        expected = [str(build_root / 'image/launcher-preflight/bin/launcher-preflight')]\n    if command != expected:\n        raise ValueError('producer_command_refused')\n    return ROLE_NAMES[role_index]\ndef generated_launcher_facts():\n    root = build_root / 'image/launcher-preflight'\n    facts = []\n    for relative in ('bin/launcher-preflight', 'lib/libapplauncher.so'):\n        path = root / relative\n        chain, leaf = parent_fds(path)\n        fd = None\n        try:\n            fd = os.open(leaf, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=chain[-1]['fd'])\n            info = os.fstat(fd)\n            if not stat.S_ISREG(info.st_mode) or (relative == 'bin/launcher-preflight' and (not info.st_mode & 73)) or info.st_uid != 1000 or (info.st_gid != 1000) or (info.st_nlink != 1):\n                raise ValueError('producer_image_shape')\n            size, digest, pin = file_digest(fd, time.monotonic() + 5)\n            ids = elf_build_ids(fd, size)\n            guard_parents(chain)\n            if fp(os.fstat(fd)) != pin or fp(os.stat(leaf, dir_fd=chain[-1]['fd'], follow_symlinks=False)) != pin:\n                raise ValueError('producer_image_changed')\n            facts.append({'path': relative, 'bytes': size, 'sha256': digest, 'generation': pin, 'buildIds': ids})\n            image_holds.append((chain, leaf, fd, pin))\n            chain = []\n            fd = None\n        finally:\n            if fd is not None:\n                os.close(fd)\n            close_parents(chain)\n    generated_image_guard()\n    return facts\ndef generated_image_guard():\n    for chain, leaf, fd, pin in image_holds:\n        guard_parents(chain)\n        if fp(os.fstat(fd)) != pin or fp(os.stat(leaf, dir_fd=chain[-1]['fd'], follow_symlinks=False)) != pin:\n            raise ValueError('producer_image_changed')\ndef close_image_holds():\n    while image_holds:\n        chain, leaf, fd, pin = image_holds.pop()\n        os.close(fd)\n        close_parents(chain)\n"
